         background: linear-gradient(145deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.9));
         box-shadow: 0 24px 70px var(--shadow);
         backdrop-filter: blur(18px);
       }

       h1 {
         margin: 0 0 10px;
         font-size: clamp(1.75rem, 5vw, 2.35rem);
         line-height: 1.05;
         letter-spacing: -0.04em;
       }

       .intro {
         margin: 0 0 28px;
         color: var(--muted);
         line-height: 1.6;
       }

       .form-field {
         display: flex;
         gap: 14px;
         align-items: flex-start;
         padding: 18px;
         border: 1px solid var(--border);
         border-radius: 18px;
         background: rgba(23, 32, 51, 0.74);
         transition:
           border-color 160ms ease,
           background 160ms ease,
           transform 160ms ease;
       }

       .form-field:focus-within {
         border-color: var(--accent-strong);
         background: rgba(30, 41, 59, 0.9);
         transform: translateY(-1px);
       }

       input[type="checkbox"] {
         width: 22px;
         height: 22px;
         margin: 2px 0 0;
         flex: 0 0 auto;
         accent-color: var(--accent);
         cursor: pointer;
       }

       label {
         display: block;
         font-weight: 700;
         line-height: 1.35;
         cursor: pointer;
       }

       .helper-text {
         margin: 6px 0 0;
         color: var(--muted);
         font-size: 0.92rem;
         line-height: 1.5;
       }

       .submit-button {
         width: 100%;
         margin-top: 22px;
         border: 0;
         border-radius: 16px;
         padding: 14px 18px;
         background: linear-gradient(135deg, var(--accent), #6366f1);
         color: white;
         font: inherit;
         font-weight: 800;
         letter-spacing: 0.01em;
         cursor: pointer;
         box-shadow: 0 16px 34px rgba(99, 102, 241, 0.3);
         transition:
           transform 160ms ease,
           box-shadow 160ms ease,
           filter 160ms ease;
       }

       .submit-button:hover {
         transform: translateY(-1px);
         box-shadow: 0 20px 42px rgba(99, 102, 241, 0.38);
         filter: brightness(1.05);
       }

       .submit-button:focus-visible {
         outline: 3px solid rgba(167, 139, 250, 0.48);
         outline-offset: 4px;
       }
     </style>
   </head>
   <body>
     <main id="root" class="app-shell"></main>

     <script>
       function CheckboxField() {
         return `
           <div class="form-field">
             <input id="terms" name="terms" type="checkbox" required />
             <div>
               <label for="terms">I agree to the terms of use</label>
               <p class="helper-text">Required to continue. Please review the terms before submitting.</p>
             </div>
           </div>
         `;
       }

       function ConsentForm() {
         return `
           <section class="consent-card" aria-labelledby="consent-title">
             <h1 id="consent-title">Confirm consent</h1>
             <p class="intro">Accept the terms of use to complete your submission.</p>
             <form>
               ${CheckboxField()}
               <button class="submit-button" type="submit">Submit</button>
             </form>
           </section>
         `;
       }

       function App() {
         return ConsentForm();
       }

       document.getElementById("root").innerHTML = App();
     </script>
   </body>
 </html>

